  "regions": [
    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "सृजति तावदशेषगुणाकरं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "पुरुषरत्नमलंकर्णं भुवः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तदपि तत्क्षणभङ्गि करोति चे-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "दहह कष्टमपण्डितता विधेः ॥ ११० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "गात्रं संकुचितं गतिर्विगलिता भ्रष्टा च दन्तावलि-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "र्दृष्टिर्नश्यति वर्धते बधिरता वक्त्रं च लालायते ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "वाक्यं नाद्रियते च बान्धवजनो भार्या न शुश्रूषते",
          "end": "line"
        },
        {
          "n": 4,
          "text": "हा कष्टं पुरुषस्य जीर्णवयसः पुत्रोप्यमित्रायते ॥ १११ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "क्षणं बालो भूत्वा क्षणमपि युवा कामरसिकः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "क्षणं वित्तैर्हीनः क्षणमपि च संपूर्णविभवः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "जराजीर्णैरङ्गैर्नट इव वलीमंडिततनु-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "र्नरः संसारान्ते विशति यमधानीजवनिकाम् ॥ ११२ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अहौ वा हारे वा बलवति रिपौ वा सुहृदि वा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "मणौ वा लोष्टे वा कुसुमशयने वा दृषदि वा ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तृणे वा स्त्रैणे वा मम समदृशो यान्ति दिवसाः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "कचित्पुण्यारण्ये शिव शिव शिवेति प्रलपतः ॥ ११३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "heading",
      "lines": [
        {
          "n": 1,
          "text": "॥ इति श्रीभर्तृहरिकृतवैराग्यशतकं संपूर्णम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
